<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{RiskAlert,User};final class RiskAlertPolicy{public function viewAny(User$u):bool{/* UI audit 2026-09-27: was any active member */return$u->memberships()->where('status','ACTIVE')->exists()&&($u->hasPermission('fraud.alert.create')||$u->hasPermission('fraud.alert.decide'));}public function view(User$u,RiskAlert$x):bool{return$x->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function update(User$u,RiskAlert$x):bool{return$this->view($u,$x)&&$u->memberships()->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}}
